#include <stdio.h>
#include <stdlib.h>

int compare(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

int main() {
    int n;
    int c[3];

    if (scanf("%d", &n) != 1) return 0;
    for (int i = 0; i < 3; i++) {
        if (scanf("%d", &c[i]) != 1) return 0;
    }

    qsort(c, 3, sizeof(int), compare);

    int count = 0;
    for (int i = 0; i < 3; i++) {
        if (n >= c[i]) {
            n -= c[i];
            count++;
        } else {
            break;
        }
    }

    printf("%d\n", count);

    return 0;
}
